import{_ as e,o as l,c as i,aw as t}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Архитектура среды выполнения JS","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/event-loop/main/runtime.md","filePath":"wiki/dev-commit/js/event-loop/main/runtime.md"}'),o={name:"wiki/dev-commit/js/event-loop/main/runtime.md"};function r(n,a,s,h,u,c){return l(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="архитектура-среды-выполнения-js" tabindex="-1">Архитектура среды выполнения JS <a class="header-anchor" href="#архитектура-среды-выполнения-js" aria-label="Permalink to &quot;Архитектура среды выполнения JS&quot;">​</a></h1><p>На примере движка V8 (Chrome, Node.js)</p><h2 id="движок-v8" tabindex="-1">Движок V8 <a class="header-anchor" href="#движок-v8" aria-label="Permalink to &quot;Движок V8&quot;">​</a></h2><ul><li><strong>V8</strong> - движок JavaScript с открытым исходным кодом</li><li>Входит в релиз Chromium</li></ul><h3 id="составные-части" tabindex="-1">Составные части <a class="header-anchor" href="#составные-части" aria-label="Permalink to &quot;Составные части&quot;">​</a></h3><ul><li>Куча (Memory Heap) - место, где происходит выделение памяти</li><li>Стек вызовов (Call Stack) - место, куда в процессе выполнения кода попадают так называемые стековые кадры</li></ul><h3 id="_1-heap" tabindex="-1">1. Heap <a class="header-anchor" href="#_1-heap" aria-label="Permalink to &quot;1. Heap&quot;">​</a></h3><ul><li><strong>Heap (куча)</strong> - структура данных, с помощью которой реализована динамически распределяемая память приложения</li><li>Куча - ссылка на определённую неструктурированную область памяти</li><li>Содержит объекты, на которые ссылаются переменные программы</li><li>memory allocation</li></ul><h3 id="_2-call-stack" tabindex="-1">2. Call Stack <a class="header-anchor" href="#_2-call-stack" aria-label="Permalink to &quot;2. Call Stack&quot;">​</a></h3><ul><li><strong>Call Stack</strong> - стек вызовов LIFO структура (последний вошедший выходит первым)</li><li>В стек помещаются и удаляются аргументы, локальные переменные функций по мере выполнения программы. Синхронные функции помещаются в стек вызова сразу. Асинхронные откладываются в специальную таблицу - Event Table, где ожидают дальнейшей обработки, чтобы не блокировать процесс выполнения программы. Видно какая функция какую вызвала (execution context)</li><li>Стек вызовов - это структура данных, которая, записывает сведения о месте в программе, где мы находимся. Если мы переходим в функцию, мы помещаем запись о ней в верхнюю часть стека. Когда мы из функции возвращаемся, мы вытаскиваем из стека самый верхний элемент и оказываемся там, откуда вызывали эту функцию. Каждая запись в стеке вызовов называется стековым кадром</li><li>Если будет достигнут максимальный размер стека (16 000), возникнет переполнение стека</li></ul><h3 id="_3-web-api" tabindex="-1">3. Web API <a class="header-anchor" href="#_3-web-api" aria-label="Permalink to &quot;3. Web API&quot;">​</a></h3><ul><li><strong>Web API</strong> - расширения браузера</li><li>Event Table и Event Queue являются частью Web API, который реализуют браузеры для того, чтобы использовать такие возможности, как асинхронные запросы, таймеры, обрабатывать DOM события и другое асинхронное поведение. Это не является стандартным функционалом JavaScript и в различных средах данное API может быть реализовано по разному</li><li>Web API - это потоки, к которым у нас нет прямого доступа, мы можем лишь выполнять обращения к ним. Они встроены в браузер, где и выполняются асинхронные действия</li></ul><hr><ul><li><strong>3.1 Event Table</strong> - таблица в которой находится информация о том, по какому событию необходимо поместить функцию в Event Queue (очередь событий)</li><li><strong>3.2 Callback/Event/Task Queue</strong> - очередь задач/событий - FIFO структура (раньше выходят элементы, которые раньше были помещены). В ней находятся асинхронные функции, для которых наступило время запуска</li><li><strong>3.3 Job Queue (ES6)</strong> - очередь заданий (микротаски) Эта конструкцию можно считать слоем, расположенном поверх очереди цикла событий. Очередь заданий — это очередь, которая присоединена к концу каждого тика в очереди цикла событий</li></ul><h3 id="_4-event-loop" tabindex="-1">4. Event Loop <a class="header-anchor" href="#_4-event-loop" aria-label="Permalink to &quot;4. Event Loop&quot;">​</a></h3><ul><li><strong>Event Loop</strong> - цикл/петля событий - наблюдает за стеком вызовов и очередью коллбэков (callback queue). Если стек вызовов пуст, цикл берёт первое событие из очереди и помещает его в стек, что приводит к запуску этого события на выполнение. Подобная итерация называется тиком (tick) цикла событий. Каждое событие - это просто коллбэк</li><li>Позволяет запланировать выполнение асинхронного кода сразу после выполнения синхронного кода</li></ul><hr><h3 id="общая-структура" tabindex="-1">Общая структура <a class="header-anchor" href="#общая-структура" aria-label="Permalink to &quot;Общая структура&quot;">​</a></h3><h3 id="виды-очередеи" tabindex="-1">Виды очередей <a class="header-anchor" href="#виды-очередеи" aria-label="Permalink to &quot;Виды очередей&quot;">​</a></h3><h3 id="анимация-работы" tabindex="-1">Анимация работы <a class="header-anchor" href="#анимация-работы" aria-label="Permalink to &quot;Анимация работы&quot;">​</a></h3><h2 id="краеугольные-камни-движка-v8" tabindex="-1">Краеугольные камни движка V8 <a class="header-anchor" href="#краеугольные-камни-движка-v8" aria-label="Permalink to &quot;Краеугольные камни движка V8&quot;">​</a></h2><ul><li>Компиляция исходного кода JavaScript непосредственно в собственный машинный код, минуя стадию промежуточного байт-кода</li><li>Эффективная система управления памятью, приводящая к быстрому объектному выделению и маленьким паузам сборки «мусора»</li><li>Введение скрытых классов и встроенных кэшей, ускоряющих доступ к свойствам и вызовам функций</li></ul>',22)])])}const b=e(o,[["render",r]]);export{m as __pageData,b as default};
